package io.github.jesterportfolio.hearth.combat;

import io.github.jesterportfolio.hearth.persistence.ServerProgressAccess;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.jesterportfolio.hearth.combat.CombatContent.*;

final class CombatPlayersTest {
    static final class Body implements CombatPlayers.PlayerPort {
        final ServerProgressAccess.Context ctx;final Object token=new Object();Pose position;boolean live=true,spectator,safe=true,cleanup,failCamera,failCleanup,nullRestore;UUID target;double health=1;final byte[] inventory={3,7,11};int restores;final CompletableFuture<Boolean> applying=new CompletableFuture<>();BooleanSupplier applyGuard;
        Body(ServerProgressAccess.Context ctx,Pose pose){this.ctx=ctx;position=pose;}
        public ServerProgressAccess.Context context(){return ctx;}public Object session(){return token;}public Pose position(){return position;}public boolean current(){return live;}
        public void spectator(UUID target){if(failCamera)throw new IllegalStateException("CAMERA_FAILED");spectator=true;this.target=target;}public void clearCamera(){target=null;}public void cleanup(){cleanup=true;if(failCleanup)throw new IllegalStateException("MODE_CLEANUP_FAILED");spectator=false;target=null;}
        public boolean safe(Pose p){return safe;}public CompletionStage<Boolean> restore(Pose p,double health,List<Effect> effects,BooleanSupplier current){restores++;applyGuard=current;if(nullRestore)return null;return applying.thenApply(ok->{if(Boolean.TRUE.equals(ok)&&current.getAsBoolean()){position=p;this.health=health;spectator=false;target=null;}return ok;});}
    }
    static final class Fixture {
        final UUID run=UUID.randomUUID(),world=UUID.randomUUID();final ServerProgressAccess access=new ServerProgressAccess();final AtomicLong generation=new AtomicLong(1),clock=new AtomicLong(100);final Queue<Runnable> queue=new ArrayDeque<>();final AtomicBoolean reject=new AtomicBoolean();
        final Body p=new Body(access.forVerifiedServerLink(run,new UUID(1,1)),new Pose(world,3,64,4,21,11)),q=new Body(access.forVerifiedServerLink(run,new UUID(1,2)),new Pose(world,5,64,4,22,12));
        final Executor owner=r->{if(reject.get())throw new RejectedExecutionException();queue.add(r);};
        final CombatPlayers bridge=new CombatPlayers(run,world,1,generation::get,owner,()->{});
        final CombatAttempt fight=new CombatAttempt(run,world,1,CombatAttemptTest.content(Pool.SHARED,2,LocationMode.START),List.of(new CombatAttempt.Entrant(p.ctx,p.token,p.position),new CombatAttempt.Entrant(q.ctx,q.token,q.position)),bridge,owner,()->{},clock::get);
        Fixture(){bridge.attach(fight,List.of(p,q));}void pump(){while(!queue.isEmpty())queue.remove().run();}
        CompletionStage<Void> revive(){return fight.revive(p.ctx,p.token,UUID.randomUUID(),"rescue");}
    }
    @Test void logicalDeathImmediatelyBlocksActionsThenProjectsSpectatorWithoutTouchingInventory(){var f=new Fixture();var before=f.p.inventory.clone();f.bridge.died(f.p);assertFalse(f.bridge.actions(f.p));assertTrue(f.bridge.movement(f.p));assertFalse(f.p.spectator);f.bridge.project();assertTrue(f.p.spectator);assertEquals(f.q.ctx.playerId(),f.p.target);assertTrue(f.bridge.actions(f.q));assertArrayEquals(before,f.p.inventory);}
    @Test void returnWaitsForPreparedNewSessionAndRetainsExactUnsafeCoordinates(){var f=new Fixture();f.bridge.died(f.p);f.q.position=new Pose(f.world,7.125,-42,8.25,94,-17);f.bridge.leave(f.q);assertTrue(f.q.cleanup);assertFalse(f.bridge.actions(f.q));var expected=f.bridge.returnPosition(f.q.ctx).orElseThrow();long revision=f.fight.snapshot().revision();assertEquals(expected,f.bridge.returnPosition(f.q.ctx).orElseThrow());assertEquals(revision,f.fight.snapshot().revision());var fresh=new Body(f.q.ctx,expected);fresh.live=false;assertThrows(IllegalStateException.class,()->f.bridge.rejoin(fresh));fresh.live=true;f.bridge.rejoin(fresh);assertFalse(f.bridge.actions(fresh));f.clock.addAndGet(3000);f.fight.poll();f.bridge.project();assertTrue(f.bridge.actions(fresh));assertEquals(expected,fresh.position);assertEquals(fresh.ctx.playerId(),f.p.target);assertFalse(f.bridge.current(f.q));}
    @Test void wrongReturnPositionHoldsWithoutRelocationOrEmptyInventory(){var f=new Fixture();f.bridge.leave(f.p);var wrong=new Body(f.p.ctx,new Pose(f.world,99,64,3,0,0));var before=wrong.inventory.clone();assertThrows(IllegalStateException.class,()->f.bridge.rejoin(wrong));assertEquals(CombatAttempt.Phase.HOLD,f.fight.snapshot().phase());assertEquals(99,wrong.position.x());assertArrayEquals(before,wrong.inventory);assertTrue(f.bridge.barrier().toCompletableFuture().isCompletedExceptionally());}
    @Test void revivalBarrierIncludesActualApplicationAndConfirmedCounter(){var f=new Fixture();f.bridge.died(f.p);f.bridge.project();var before=f.p.inventory.clone();var request=f.revive();var barrier=f.bridge.barrier();assertFalse(barrier.toCompletableFuture().isDone());assertTrue(f.p.applyGuard.getAsBoolean());f.bridge.project();assertTrue(f.p.spectator);f.p.applying.complete(true);f.pump();f.bridge.project();assertFalse(request.toCompletableFuture().isCompletedExceptionally());assertFalse(barrier.toCompletableFuture().isCompletedExceptionally());assertTrue(barrier.toCompletableFuture().isDone());assertEquals(1,f.fight.snapshot().sharedUsed());assertTrue(f.bridge.actions(f.p));assertFalse(f.p.spectator);assertEquals(0.5,f.p.health);assertArrayEquals(before,f.p.inventory);}
    @Test void leavingDuringRestoreRejectsOldApplyAndPreservesReservation(){var f=new Fixture();f.bridge.died(f.p);var pending=f.revive();f.bridge.leave(f.p);assertFalse(f.p.applyGuard.getAsBoolean());var fresh=new Body(f.p.ctx,f.p.position);f.bridge.rejoin(fresh);f.p.applying.complete(true);f.pump();assertTrue(pending.toCompletableFuture().isCompletedExceptionally());assertEquals(CombatAttempt.Phase.HOLD,f.fight.snapshot().phase());assertEquals(0,f.fight.snapshot().sharedUsed());assertEquals(1,f.fight.snapshot().reserved());assertEquals(1,fresh.health);assertTrue(f.bridge.barrier().toCompletableFuture().isCompletedExceptionally());}
    @Test void changedWorldGenerationPreventsLatePhysicalApplyAndOtherRunRemainsActive(){var f=new Fixture();var other=new Fixture();f.bridge.died(f.p);var pending=f.revive();f.generation.incrementAndGet();assertFalse(f.p.applyGuard.getAsBoolean());f.bridge.project();f.p.applying.complete(true);f.pump();assertTrue(pending.toCompletableFuture().isCompletedExceptionally());assertEquals(1,f.p.health);assertFalse(f.bridge.current(f.p));assertTrue(other.bridge.actions(other.p));}
    @Test void failedApplyAndCameraFailureDoNotBecomeSuccess(){var f=new Fixture();f.bridge.died(f.p);var result=f.revive();f.p.applying.completeExceptionally(new IllegalStateException("MOVE_FAILED"));f.pump();assertTrue(result.toCompletableFuture().isCompletedExceptionally());assertFalse(f.bridge.actions(f.p));assertEquals(0,f.fight.snapshot().sharedUsed());assertTrue(f.bridge.barrier().toCompletableFuture().isCompletedExceptionally());var camera=new Fixture();camera.bridge.died(camera.p);camera.p.failCamera=true;assertThrows(IllegalStateException.class,camera.bridge::project);assertEquals(CombatAttempt.Phase.HOLD,camera.fight.snapshot().phase());assertTrue(camera.fight.snapshot().members().getFirst().dead());}
    @Test void closeInvalidatesPendingWorkAndCleansAllPortsWithoutFalseBarrierSuccess(){var f=new Fixture();f.bridge.died(f.p);var pending=f.revive();f.bridge.close();assertTrue(f.p.cleanup&&f.q.cleanup);assertFalse(f.p.applyGuard.getAsBoolean());f.p.applying.complete(true);f.pump();assertTrue(pending.toCompletableFuture().isCompletedExceptionally());assertEquals(0,f.fight.snapshot().sharedUsed());assertTrue(f.bridge.barrier().toCompletableFuture().isCompletedExceptionally());assertFalse(f.bridge.actions(f.p));}
    @Test void terminalDeadPlayerWaitsForExplicitReleaseWhileSurvivorCanContinue(){var f=new Fixture();f.bridge.died(f.p);f.fight.victory();f.bridge.project();assertFalse(f.bridge.actions(f.p));assertTrue(f.p.spectator);assertNull(f.p.target);assertTrue(f.bridge.actions(f.q));f.bridge.leave(f.p);assertTrue(f.p.cleanup);assertFalse(f.p.spectator);assertTrue(f.bridge.returnPosition(f.p.ctx).isEmpty());}
    @Test void wrongContextAndDuplicatePortAreRejectedBeforeUse(){var f=new Fixture();var stranger=new Body(f.access.forVerifiedServerLink(UUID.randomUUID(),f.p.ctx.playerId()),f.p.position);assertFalse(f.bridge.current(stranger));assertThrows(IllegalStateException.class,()->f.bridge.rejoin(stranger));assertThrows(IllegalStateException.class,()->f.bridge.rejoin(f.p));assertThrows(IllegalStateException.class,()->f.bridge.attach(f.fight,List.of(f.p,f.q)));assertFalse(f.bridge.actions(stranger));}
    @Test void hazardAndPositionChecksNeverCorrectCoordinates(){assertTrue(CombatPlayers.safeCells("STONE","AIR","AIR",true,true,true));for(String bad:List.of("MAGMA_BLOCK","CAMPFIRE","CACTUS","POWDER_SNOW","LAVA","WITHER_ROSE"))assertFalse(CombatPlayers.safeCells(bad,"AIR","AIR",true,true,true));assertFalse(CombatPlayers.safeCells("STONE","FIRE","AIR",true,true,true));assertFalse(CombatPlayers.safeCells("AIR","AIR","AIR",false,true,true));assertFalse(CombatPlayers.safeCells("STONE","STONE","AIR",true,false,true));UUID world=UUID.randomUUID();var p=new Pose(world,1.125,-42,3.25,91,18);assertTrue(CombatPlayers.samePosition(p,p));assertTrue(CombatPlayers.samePosition(p,new Pose(world,1.125,-42,3.25,451,18)));assertFalse(CombatPlayers.samePosition(p,new Pose(world,1.125,-42,3.25,0,18)));assertFalse(CombatPlayers.samePosition(p,new Pose(UUID.randomUUID(),1.125,-42,3.25,91,18)));}
    @Test void rejectedOwnerDoesNotApplyAnythingToNewSession() throws Exception {var f=new Fixture();f.bridge.died(f.p);var request=f.revive();f.reject.set(true);var worker=new Thread(()->f.p.applying.completeExceptionally(new IllegalStateException("DISCONNECTED")));worker.start();worker.join();assertTrue(request.toCompletableFuture().isCompletedExceptionally());f.bridge.project();assertEquals(CombatAttempt.Phase.HOLD,f.fight.snapshot().phase());assertEquals(0,f.fight.snapshot().sharedUsed());}
    @Test void cleanupFailureDoesNotSkipOtherPlayerOrEraseHold(){var f=new Fixture();f.p.failCleanup=true;assertThrows(IllegalStateException.class,f.bridge::close);assertTrue(f.p.cleanup&&f.q.cleanup);assertTrue(f.bridge.barrier().toCompletableFuture().isCompletedExceptionally());assertFalse(f.bridge.current(f.q));}

    @Test void restoreHealthCannotUnderflowToVanillaDeath(){assertEquals(10,CombatPlayers.restoredHealth(20,0.5));for(double bad:new double[]{0,Double.NaN,Double.MIN_VALUE,1.1})assertThrows(IllegalStateException.class,()->CombatPlayers.restoredHealth(20,bad));}

    @Test void missingApplyFutureFailsInsteadOfLeavingBarrierPending(){var f=new Fixture();f.bridge.died(f.p);f.p.nullRestore=true;var result=f.revive();f.pump();assertTrue(result.toCompletableFuture().isCompletedExceptionally());assertTrue(f.bridge.barrier().toCompletableFuture().isCompletedExceptionally());assertEquals(0,f.fight.snapshot().sharedUsed());}

    @Test void quitCleanupFailureIsHeldEvenAfterConnectionRemoval(){var f=new Fixture();f.p.failCleanup=true;assertThrows(IllegalStateException.class,()->f.bridge.leave(f.p));assertFalse(f.bridge.current(f.p));assertEquals(CombatAttempt.Phase.HOLD,f.fight.snapshot().phase());assertTrue(f.bridge.barrier().toCompletableFuture().isCompletedExceptionally());}

}
